  const server = await loadGameServer(job.serverId!);
  if (SANDBOX) {
    // No VM exists, so nothing can be proven. Say that, rather than simulating a
    // success message the production path is no longer willing to send.
    await notify(
      server.userId,
      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  const family = server.osTemplate.family as GameFamily;
  if (!GAME_FAMILIES.includes(family)) {
    throw new Error(`game update: ${server.hostname} is not a game server`);
  }
  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
  const password = serverRootPassword(server);
  if (!server.ipAddress || !password) {
    throw new Error("game update: server has no IP/password yet");
  }
  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
  const href = `/dashboard/servers/${server.id}`;

  const remote = updateCommand(family);
  let stdout = "";
  try {
    const r = await execFileP(
      "sshpass",
      [
        "-p",
        password,
        "ssh",
        "-o",
        "StrictHostKeyChecking=no",
        "-o",
        "UserKnownHostsFile=/dev/null",
        "-o",
        "ConnectTimeout=15",
        `root@${server.ipAddress}`,
        remote,
      ],
      { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
    );
    stdout = String(r.stdout ?? "");
  } catch (e: any) {
    // A non-zero exit is now possible and meaningful, but the markers may still
    // have been printed before whatever went wrong — keep them and let the
    // verdict decide, rather than discarding evidence.
    stdout = String(e?.stdout ?? "");
